<?php
declare(strict_types=1);
ini_set('display_errors','0');
error_reporting(E_ALL);
header('X-Content-Type-Options: nosniff');
header('Cache-Control: private, no-store');
header('Referrer-Policy: strict-origin-when-cross-origin');
header('X-Frame-Options: DENY');
header('Content-Security-Policy: default-src \'self\'; style-src \'self\' \'unsafe-inline\'; script-src \'self\' \'unsafe-inline\'; img-src \'self\' data:; base-uri \'self\'; form-action \'self\'');
$secure = !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off';
ini_set('session.use_strict_mode','1');
session_set_cookie_params(['httponly'=>true,'secure'=>$secure,'samesite'=>'Lax','path'=>'/rdc']);
session_start();
function esc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function db():PDO {static $p=null;if($p)return $p; $dir=__DIR__.'/data';if(!is_dir($dir))mkdir($dir,0700,true); $p=new PDO('sqlite:'.$dir.'/odonto_em_dia.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec('PRAGMA busy_timeout=5000');$p->exec('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP)');$p->exec('CREATE TABLE IF NOT EXISTS clinics(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,name TEXT NOT NULL,cnpj TEXT DEFAULT \'\',city TEXT DEFAULT \'\',state TEXT DEFAULT \'\',rt_name TEXT DEFAULT \'\',rt_cro TEXT DEFAULT \'\',chairs INTEGER DEFAULT 1,has_xray INTEGER DEFAULT 0,has_sedation INTEGER DEFAULT 0,sterilization TEXT DEFAULT \'interna\',created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id))');$p->exec('CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY,clinic_id INTEGER NOT NULL,group_no INTEGER NOT NULL,status TEXT DEFAULT \'pendente\',responsible TEXT DEFAULT \'\',due_date TEXT DEFAULT \'\',notes TEXT DEFAULT \'\',updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(clinic_id,group_no))');$p->exec('CREATE TABLE IF NOT EXISTS checks(id INTEGER PRIMARY KEY,clinic_id INTEGER NOT NULL,code TEXT NOT NULL,status TEXT DEFAULT \'nao_avaliado\',notes TEXT DEFAULT \'\',UNIQUE(clinic_id,code))');return $p;}
function groups():array{return [1=>'Licenciamento e regularização',2=>'Responsabilidades técnicas e equipe',3=>'Estrutura física e instalações',4=>'Equipamentos e manutenção',5=>'Água e condições ambientais',6=>'Higienização e limpeza',7=>'Biossegurança e EPIs',8=>'Processamento de produtos para saúde',9=>'Resíduos de serviços de saúde',10=>'Segurança do paciente',11=>'Medicamentos e insumos',12=>'Controle de infecções',13=>'Prontuários e registros',14=>'Radiologia (quando aplicável)',15=>'Sedação e urgências (quando aplicável)',16=>'Capacitação e treinamento',17=>'Monitoramento e melhoria contínua'];}
// Os grupos acima são categorias de trabalho para organização da plataforma; não são transcrição literal do artigo 113.
function checks():array{return ['A01'=>'Licença sanitária e documentos de regularização','A02'=>'Responsável técnico identificado e documentado','A03'=>'Rotinas de higienização registradas','A04'=>'Controle de esterilização documentado','A05'=>'Rastreabilidade dos materiais processados','A06'=>'PGRSS avaliado e atualizado','A07'=>'Registros de capacitação da equipe','A08'=>'Manutenção dos equipamentos documentada','A09'=>'Registros de incidentes e ações corretivas','A10'=>'Protocolos de atendimento de urgência revisados','A11'=>'Condições de armazenamento verificadas','A12'=>'Registros de controle de qualidade disponíveis','A13'=>'Rotina de avaliação de riscos registrada','A14'=>'Prontuários organizados e protegidos','A15'=>'Documentação de radiologia verificada, se aplicável'];}
function csrf():string {if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function token():string{return '<input type="hidden" name="csrf" value="'.esc(csrf()).'">';}
function redirect(string $url='?'):never{header('Location: '.$url, true,303);exit;}
function user():?int{return isset($_SESSION['uid'])?(int)$_SESSION['uid']:null;}
function clinic():?array{if(!user())return null;$s=db()->prepare('SELECT * FROM clinics WHERE user_id=? ORDER BY id LIMIT 1');$s->execute([user()]);return $s->fetch()?:null;}
function flash(string $s):void{$_SESSION['flash']=$s;}
function h(string $page):void {$title='Odonto em Dia';echo '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$title.'</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><a class="brand" href="?page=inicio">◇ Odonto <span>em Dia</span></a><nav>';if(user())echo '<a href="?page=painel">Painel</a><a href="?page=diagnostico">Perfil</a><a href="?page=documentos">Documentos</a><a href="?page=inspecao">Autoinspeção</a><a href="?page=sair">Sair</a>';echo '</nav></header><main>';if(!empty($_SESSION['flash'])){echo '<div class="notice">'.esc($_SESSION['flash']).'</div>';unset($_SESSION['flash']);}echo '<div class="eyebrow">ODONTO EM DIA &nbsp; / &nbsp; ORGANIZAÇÃO DOCUMENTAL</div><h1>'.esc($page).'</h1>';}
function foot():void {echo '<footer>Odonto em Dia · Modelos auxiliares. A avaliação de aplicabilidade, elaboração, revisão e implementação cabem ao responsável técnico. A plataforma não emite certificados da Anvisa nem garante aprovação em inspeções.</footer></main></body></html>';}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals(csrf(),(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada. Recarregue a página.');}
 $act=(string)($_POST['act']??'');
 if($act==='register'){
  // Durante o piloto, apenas uma conta inicial pode ser criada. Compradores precisarão de provisionamento após pagamento validado.
  if((int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn()>=1){flash('O cadastro de testes está fechado. Entre com sua conta existente.');redirect('?page=entrar');}
  $email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');
  if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<12){flash('Use um e-mail válido e senha de pelo menos 12 caracteres.');redirect('?page=entrar');}
  try{$q=db()->prepare('INSERT INTO users(email,password) VALUES(?,?)');$q->execute([$email,password_hash($pw,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['uid']=(int)db()->lastInsertId();redirect('?page=diagnostico');}catch(PDOException $e){flash('Não foi possível cadastrar este e-mail.');redirect('?page=entrar');}
 }
 if($act==='login'){$q=db()->prepare('SELECT * FROM users WHERE email=?');$q->execute([strtolower(trim((string)($_POST['email']??'')))]);$u=$q->fetch();if($u && password_verify((string)($_POST['password']??''),$u['password'])){session_regenerate_id(true);$_SESSION['uid']=(int)$u['id'];redirect('?page=painel');}flash('E-mail ou senha incorretos.');redirect('?page=entrar');}
 if(!user()){http_response_code(401);exit('Faça login.');}
 if($act==='clinic'){$name=mb_substr(trim((string)($_POST['name']??'')),0,180);if(!$name){flash('Informe o nome da clínica.');redirect('?page=diagnostico');} $vals=[$name,mb_substr(trim((string)($_POST['cnpj']??'')),0,18),mb_substr(trim((string)($_POST['city']??'')),0,120),mb_substr(trim((string)($_POST['state']??'')),0,2),mb_substr(trim((string)($_POST['rt_name']??'')),0,150),mb_substr(trim((string)($_POST['rt_cro']??'')),0,45),max(1,min(200,(int)($_POST['chairs']??1))),isset($_POST['has_xray'])?1:0,isset($_POST['has_sedation'])?1:0,in_array(($_POST['sterilization']??''),['interna','terceirizada','mista'],true)?$_POST['sterilization']:'interna'];$c=clinic();if($c){$s=db()->prepare('UPDATE clinics SET name=?,cnpj=?,city=?,state=?,rt_name=?,rt_cro=?,chairs=?,has_xray=?,has_sedation=?,sterilization=? WHERE id=? AND user_id=?');$s->execute([...$vals,$c['id'],user()]);}else{$s=db()->prepare('INSERT INTO clinics(name,cnpj,city,state,rt_name,rt_cro,chairs,has_xray,has_sedation,sterilization,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->execute([...$vals,user()]);}flash('Dados salvos. Revise os requisitos com o responsável técnico.');redirect('?page=painel');}
 $c=clinic();if(!$c){redirect('?page=diagnostico');}
 if($act==='task'){$n=(int)($_POST['number']??0);$status=(string)($_POST['status']??'pendente');if(!isset(groups()[$n])||!in_array($status,['pendente','em_andamento','revisao_rt','concluido'],true))exit('Dados inválidos');$s=db()->prepare('INSERT INTO tasks(clinic_id,group_no,status,responsible,due_date,notes) VALUES(?,?,?,?,?,?) ON CONFLICT(clinic_id,group_no) DO UPDATE SET status=excluded.status,responsible=excluded.responsible,due_date=excluded.due_date,notes=excluded.notes,updated_at=CURRENT_TIMESTAMP');$due=(string)($_POST['due_date']??'');if($due&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due))$due='';$s->execute([$c['id'],$n,$status,mb_substr(trim((string)($_POST['responsible']??'')),0,120),$due,mb_substr(trim((string)($_POST['notes']??'')),0,1000)]);flash('Acompanhamento atualizado.');redirect('?page=painel');}
 if($act==='check'){$code=(string)($_POST['code']??'');$status=(string)($_POST['status']??'nao_avaliado');if(!isset(checks()[$code])||!in_array($status,['nao_avaliado','pendente','em_andamento','verificado','nao_aplicavel'],true))exit('Dados inválidos');$s=db()->prepare('INSERT INTO checks(clinic_id,code,status,notes) VALUES(?,?,?,?) ON CONFLICT(clinic_id,code) DO UPDATE SET status=excluded.status,notes=excluded.notes');$s->execute([$c['id'],$code,$status,mb_substr(trim((string)($_POST['notes']??'')),0,1000)]);flash('Verificação atualizada.');redirect('?page=inspecao');}
}
$page=(string)($_GET['page']??'inicio');
if($page==='inicio'){require __DIR__.'/landing.php';exit;}
if($page==='demo'){require __DIR__.'/demo.php';exit;}
if($page==='sair'){$_SESSION=[];session_destroy();redirect('?page=entrar');}
if(!user()){$page='entrar';h('Sua clínica mais organizada');echo '<p class="lead">Acompanhe documentos, responsabilidades e pendências sanitárias em um único lugar.</p><div class="two"><section class="card"><h2>Entrar</h2><form method="post">'.token().'<input type="hidden" name="act" value="login"><label>E-mail<input name="email" type="email" required autocomplete="email"></label><label>Senha<input name="password" type="password" required autocomplete="current-password"></label><button>Entrar no painel</button></form></section><section class="card"><h2>Primeiro acesso do proprietário</h2><p class="muted">Somente o primeiro cadastro é permitido nesta versão de avaliação. Não inclua dados de pacientes.</p><form method="post">'.token().'<input type="hidden" name="act" value="register"><label>E-mail<input name="email" type="email" required></label><label>Senha (12 caracteres ou mais)<input name="password" type="password" required minlength="12" autocomplete="new-password"></label><button class="secondary">Criar conta</button></form></section></div>';foot();exit;}
$c=clinic();if(!$c&&$page!=='diagnostico')redirect('?page=diagnostico');
if($page==='diagnostico'){require __DIR__.'/onboarding.php';exit;}
if($page==='painel'){$s=db()->prepare('SELECT * FROM tasks WHERE clinic_id=?');$s->execute([$c['id']]);$taskRows=[];foreach($s as $t)$taskRows[$t['group_no']]=$t;$done=count(array_filter($taskRows,fn($v)=>$v['status']==='concluido'));h('Painel de adequação');echo '<p class="lead">'.esc($c['name']).' · Acompanhamento de categorias documentais</p><div class="stats"><div class="stat"><strong>'.count(groups()).'</strong><span>Categorias</span></div><div class="stat"><strong>'.$done.'</strong><span>Marcadas concluídas</span></div><div class="stat"><strong>'.(count(groups())-$done).'</strong><span>Acompanhar</span></div></div><div class="warn">Concluído significa marcação interna, não conformidade sanitária comprovada. Verifique os requisitos aplicáveis com o RT.</div><div class="stack">';foreach(groups() as $n=>$name){$t=$taskRows[$n]??[];echo '<section class="card task"><div class="tasktop"><div><small>GRUPO '.str_pad((string)$n,2,'0',STR_PAD_LEFT).'</small><h3>'.esc($name).'</h3></div><span class="pill">'.esc(str_replace('_',' ',$t['status']??'pendente')).'</span></div><form method="post">'.token().'<input type="hidden" name="act" value="task"><input type="hidden" name="number" value="'.$n.'"><div class="three"><label>Situação<select name="status">';foreach(['pendente'=>'Pendente','em_andamento'=>'Em andamento','revisao_rt'=>'Em revisão pelo RT','concluido'=>'Concluído internamente'] as $k=>$v)echo '<option value="'.$k.'" '.(($t['status']??'pendente')===$k?'selected':'').'>'.$v.'</option>';echo '</select></label><label>Responsável<input name="responsible" value="'.esc($t['responsible']??'').'"></label><label>Prazo<input type="date" name="due_date" value="'.esc($t['due_date']??'').'"></label></div><label>Observações<input name="notes" maxlength="1000" value="'.esc($t['notes']??'').'"></label><button class="small">Salvar</button></form></section>';}echo '</div>';foot();exit;}
if($page==='documentos'){$items=['POP de higienização de superfícies','POP de processamento e esterilização','POP de higienização das mãos','POP de gerenciamento de resíduos','Registro de treinamento','Registro de manutenção preventiva'];h('Biblioteca documental');echo '<p class="lead">Modelos iniciais de trabalho para personalizar, imprimir e submeter à revisão do responsável técnico.</p><div class="warn">Estes modelos são esqueletos de documentação, não procedimentos clínicos completos. A aprovação do RT é necessária antes do uso.</div><div class="stack">';foreach($items as $i=>$name){echo '<div class="card docrow"><div><small>MODELO '.($i+1).'</small><h3>'.esc($name).'</h3><p class="muted">Identificação, objetivo, aplicação, materiais, procedimento, registros, revisão e aprovação.</p></div><a class="btn" href="?page=exportar&modelo='.$i.'">Gerar modelo</a></div>';}echo '</div>';foot();exit;}
if($page==='exportar'){$arr=['POP de higienização de superfícies','POP de processamento e esterilização','POP de higienização das mãos','POP de gerenciamento de resíduos','Registro de treinamento','Registro de manutenção preventiva'];$i=filter_var($_GET['modelo']??null,FILTER_VALIDATE_INT);if($i===false||$i<0||$i>=count($arr)){http_response_code(404);exit('Modelo inválido');}header('Content-Type: text/html; charset=utf-8');header('Content-Disposition: attachment; filename="modelo-odonto-'.($i+1).'.html"');echo '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>'.esc($arr[$i]).'</title><style>body{font:16px Arial;line-height:1.6;max-width:850px;margin:50px auto;color:#1b3040}h1{color:#0e766d}section{border-bottom:1px solid #ddd;padding:14px 0}em{color:#a34d19}</style><h1>'.esc($arr[$i]).'</h1><p><b>Estabelecimento:</b> '.esc($c['name']).'<br><b>CNPJ:</b> '.esc($c['cnpj']).'<br><b>Responsável técnico:</b> '.esc($c['rt_name']).' / '.esc($c['rt_cro']).'</p><p><em>MINUTA NÃO APROVADA. Completar com os procedimentos específicos da clínica, validar com o RT e manter evidências da implementação.</em></p>';foreach(['Código, versão e data de vigência','Objetivo e abrangência','Responsáveis e funções','Materiais, produtos e equipamentos','Descrição detalhada do procedimento (a preencher pelo RT)','Critérios de controle e monitoramento','Registros e formulários relacionados','Tratamento de não conformidades','Referências técnicas e revisão','Aprovação do responsável técnico'] as $s)echo '<section><b>'.esc($s).'</b><p>Preencher e validar conforme o processo real do estabelecimento.</p></section>';echo '</html>';exit;}
if($page==='inspecao'){$s=db()->prepare('SELECT * FROM checks WHERE clinic_id=?');$s->execute([$c['id']]);$rows=[];foreach($s as $r)$rows[$r['code']]=$r;h('Autoinspeção 360');echo '<p class="lead">Verificações iniciais para mapear evidências e pendências. Amostra operacional, não reprodução integral do roteiro oficial de inspeção da Anvisa.</p><div class="stack">';foreach(checks() as $code=>$name){$r=$rows[$code]??[];echo '<section class="card task"><div class="tasktop"><div><small>'.esc($code).'</small><h3>'.esc($name).'</h3></div></div><form method="post">'.token().'<input type="hidden" name="act" value="check"><input type="hidden" name="code" value="'.esc($code).'"><div class="two"><label>Avaliação<select name="status">';foreach(['nao_avaliado'=>'Não avaliado','pendente'=>'Pendente','em_andamento'=>'Em andamento','verificado'=>'Verificado internamente','nao_aplicavel'=>'Não aplicável (justificar)'] as $k=>$v)echo '<option value="'.$k.'" '.(($r['status']??'nao_avaliado')===$k?'selected':'').'>'.$v.'</option>';echo '</select></label><label>Registro / evidência / justificativa<input name="notes" value="'.esc($r['notes']??'').'"></label></div><button class="small">Salvar verificação</button></form></section>';}echo '</div>';foot();exit;}
redirect('?page=painel');